from __future__ import annotations

import sympy as sp

from .cache import CACHE, sample_identity_key
from .samples import AlgebraicRoot, RationalSample, Sample


def _as_sample(value: Sample | sp.Expr | None) -> Sample | None:
    if value is None:
        return None
    if isinstance(value, (RationalSample, AlgebraicRoot)):
        return value
    raise TypeError("CAD sector bounds must be explicit semialg Sample objects")


def _best_intvl(sample: Sample):
    if isinstance(sample, AlgebraicRoot) and sample.fiber_context is not None:
        cached = sample.fiber_context.best_root_intvl(sample.root_index)
        if cached is not None:
            return cached
    return sample.interval


def choose_sector_sample(left: Sample | None, right: Sample | None) -> RationalSample:
    """Choose a rational sample in the sector between two explicit bounds."""

    left = _as_sample(left)
    right = _as_sample(right)
    if left is None and right is None:
        return RationalSample(sp.Integer(0))
    if left is None:
        return RationalSample(right.interval.left - 1)
    if right is None:
        return RationalSample(left.interval.right + 1)
    left_intvl = _best_intvl(left)
    right_intvl = _best_intvl(right)
    if left_intvl.right < right_intvl.left:
        separator = sp.Rational(left_intvl.right + right_intvl.left, 2)
        CACHE.sector_separators.put(
            ("sector-between", sample_identity_key(left), sample_identity_key(right)), separator
        )
        return RationalSample(separator)
    cache_key = ("sector-between", sample_identity_key(left), sample_identity_key(right))
    separator = CACHE.sector_separators.get(cache_key)
    if separator is not None:
        return RationalSample(separator)
    cached = CACHE.specializations.get(cache_key)
    if cached is not None:
        CACHE.stats.specialization_hits += 1
        return RationalSample(cached)
    CACHE.stats.specialization_misses += 1
    # Overlapping isolating intervals can occur before refinement.  Delegate
    # exact separation to the shared certified-root facility so CAD lifting,
    # region sampling, and standalone algebraic callers use one policy.
    from .roots import rational_between_algebraic_reals

    value = rational_between_algebraic_reals(left, right)
    CACHE.specializations.put(cache_key, value)
    return RationalSample(value)
